<script>
 import { computeOptimizationLesson, gradientDescent } from '@/lib/formula-lessons/optimization-primitives.mjs';
 export let lesson; export let spec;
 let alpha=spec.alpha; $: r=computeOptimizationLesson({initial:spec.initial,curvature:spec.curvature,alpha:Number(alpha),steps:spec.steps,sampleGradients:spec.sampleGradients,batchIndices:spec.batchIndices}); $: stable=gradientDescent({initial:spec.initial,curvature:spec.curvature,alpha:spec.stableExample,steps:spec.steps}); $: unstable=gradientDescent({initial:spec.initial,curvature:spec.curvature,alpha:spec.unstableExample,steps:spec.steps}); const f=(v,d=4)=>Number(v).toFixed(d);
</script>
<div class="grid" data-optimization-primitives-lesson data-focus={lesson.focus}><section class="panel"><p class="eyebrow">Gradient descent trajectory</p><h6>α={f(alpha,2)} · final f={f(r.final.value)}</h6><label>learning rate α <output>{f(alpha,2)}</output><input bind:value={alpha} type="range" min="0.02" max="0.75" step="0.01"/></label><div class="trajectory">{#each r.trajectory as row}<i style={`height:${Math.max(3,Math.min(70,5+8*Math.log10(1+row.value)))}px`} title={`step ${row.step}: ${f(row.value)}`}></i>{/each}</div><div class="check">quadratic stability criterion α &lt; {f(2/Math.max(...spec.curvature),3)} → {r.stableForQuadratic?'stable range':'outside stable range'}</div></section><section class="panel"><p class="eyebrow">Stable vs unstable + minibatch</p><table><tbody><tr><th>α={spec.stableExample}</th><td>{f(stable[0].value)} → {f(stable.at(-1).value)}</td></tr><tr><th>α={spec.unstableExample}</th><td>{f(unstable[0].value)} → {f(unstable.at(-1).value)}</td></tr><tr><th>Σ batch gradients</th><td>[{r.batchGradient.map(v=>f(v)).join(', ')}]</td></tr></tbody></table><p class="small">The source mini-batch update uses a sum over the selected batch. Whether an implementation averages instead is an optimizer convention that changes the effective learning-rate scale.</p></section></div>
<style>.grid{display:grid;grid-template-columns:1fr 1fr;gap:.8rem}.panel{border:1px solid var(--color-border);border-radius:1rem;background:var(--color-background);padding:1rem}.eyebrow{margin:0;font-size:.66rem;font-weight:900;text-transform:uppercase;letter-spacing:.1em;color:var(--color-muted-foreground)}h6{margin:.25rem 0 .7rem}.panel label{display:grid;grid-template-columns:1fr auto;gap:.2rem;font-size:.73rem;font-weight:800}.panel input{grid-column:1/-1;min-height:30px}.trajectory{height:75px;display:flex;align-items:end;gap:3px;margin:.7rem 0;border-bottom:1px solid var(--color-border)}.trajectory i{flex:1;background:var(--color-primary);border-radius:3px 3px 0 0}.check,.small{border-radius:.7rem;background:var(--color-muted);padding:.7rem;font-size:.72rem;line-height:1.55}table{width:100%;border-collapse:collapse;font-size:.73rem}th,td{padding:.55rem;border-bottom:1px solid var(--color-border);text-align:left}@media(max-width:760px){.grid{grid-template-columns:1fr}}</style>
